SELECT json_extract(payload,'$.organization_id') AS organization_id,COUNT(DISTINCT patient) AS patient_count FROM records WHERE stream='labs' AND json_extract(payload,'$.name') IN ('HbA1c','Hemoglobin A1c','Hemoglobin A1c/Hemoglobin.total') AND json_extract(payload,'$.unit')='%' AND json_type(payload,'$.value') IN ('integer','real') AND json_extract(payload,'$.organization_id') IS NOT NULL GROUP BY 1 ORDER BY 1;
